    return chunks


def hard_wrap(text: str, max_chars: int = 1400, overlap: int = 180):
    text = text.strip()
    if not text:
        return []
    chunks = []
    start = 0
    while start < len(text):
        chunks.append(("", 1, text[start:start + max_chars]))
        if start + max_chars >= len(text):
            break
        start += max_chars - overlap
    return chunks


